package io.github.syldegil.autotunnel;
import android.app.*;import android.content.*;import android.graphics.Typeface;import android.content.res.ColorStateList;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
/** Native touch targets with decorative vector icons and explicit accessible labels. */
final class DashboardUi {
 static int dp(Context c,int n){return AppStyle.dp(c,n);}
 static LinearLayout column(Context c){LinearLayout l=new LinearLayout(c);l.setOrientation(LinearLayout.VERTICAL);return l;}
 static TextView text(LinearLayout p,String s,int size,boolean strong){Context c=p.getContext();TextView t=new TextView(c);t.setText(s);t.setTextSize(size);t.setTextColor(strong?AppStyle.ink(c):AppStyle.muted(c));if(strong)t.setTypeface(null,Typeface.BOLD);p.addView(t);return t;}
 static LinearLayout card(LinearLayout p){Context c=p.getContext();LinearLayout l=column(c);int d=dp(c,18);l.setPadding(d,d,d,d);AppStyle.card(l);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(c,12),0,0);p.addView(l,lp);return l;}
 static LinearLayout row(LinearLayout p){LinearLayout l=new LinearLayout(p.getContext());l.setGravity(Gravity.CENTER_VERTICAL);l.setBaselineAligned(false);p.addView(l,new LinearLayout.LayoutParams(-1,-2));return l;}
 static Button action(LinearLayout p,String title,Runnable run){Button b=new Button(p.getContext());b.setText(title);AppStyle.button(b);b.setOnClickListener(v->run.run());p.addView(b,new LinearLayout.LayoutParams(-1,-2));return b;}
 static void primary(Button b){Context c=b.getContext();b.setTextColor(AppStyle.color(c,"#ffffff","#10281f"));GradientDrawable s=InspectorVisuals.shape(AppStyle.green(c),18,c);b.setBackground(new RippleDrawable(ColorStateList.valueOf(0x33777777),s,null));}
 static LinearLayout tile(LinearLayout row,String icon,String title,String subtitle,Runnable action){Context c=row.getContext();LinearLayout tile=column(c);int d=dp(c,16);tile.setPadding(d,d,d,d);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(c,4),dp(c,10),dp(c,4),0);row.addView(tile,lp);tile.setMinimumHeight(dp(c,126));tile.setBackground(new RippleDrawable(ColorStateList.valueOf(0x22777777),InspectorVisuals.shape(AppStyle.panel(c),22,c),null));tile.addView(new InspectorVisuals.Icon(c,icon,AppStyle.green(c)),new LinearLayout.LayoutParams(dp(c,32),dp(c,32)));TextView t=text(tile,title,18,true);t.setPadding(0,dp(c,10),0,dp(c,3));text(tile,subtitle,12,false);tile.setFocusable(true);tile.setClickable(true);tile.setContentDescription(title+". "+subtitle);tile.setOnClickListener(v->action.run());return tile;}
 static void info(Context c,String title,String body){new AlertDialog.Builder(c).setTitle(title).setMessage(body).setPositiveButton("Fermer",null).show();}
 static void header(Activity a,LinearLayout root,String title){LinearLayout row=row(root);Button back=action(row,"‹",a::finish);back.setContentDescription("Retour");back.setLayoutParams(new LinearLayout.LayoutParams(dp(a,48),dp(a,48)));TextView t=text(row,title,26,true);t.setPadding(dp(a,12),0,0,0);if(android.os.Build.VERSION.SDK_INT>=28)t.setAccessibilityHeading(true);}
}
